-- Neon 콘솔용 스테이징 적재. 00_staging.sql 과 결과는 같지만 `\copy`(psql 전용
-- 메타명령) 대신 INSERT 를 씁니다 — Neon SQL Editor 는 `\copy` 를 실행하지
-- 못하고, 그 상태로 30_insert.sql 을 돌리면 빈 스테이징에서 0행이 적재됩니다.
-- psql 을 쓰신다면 이 파일 대신 00_staging.sql 을 쓰셔도 됩니다.

DROP TABLE IF EXISTS stg_spb_2608;
CREATE TABLE stg_spb_2608 (
  so_no            text,
  so_seq           int,
  so_ref           text,
  tgl              date,
  target_delivery  text,
  buyer            text,
  pic              text,
  destination      text,
  brand            text,
  kategori         text,
  tipe             text,
  item_no          text,
  deskripsi        text,
  qty              numeric,
  harga            numeric,
  total            numeric,
  mata_uang        text
);


-- 확인 — 83 / 58 / 405 / 523816000 이어야 원본과 일치합니다
SELECT count(*) AS baris, count(DISTINCT so_no) AS transaksi,
       sum(qty) AS qty, sum(total) AS nilai,
       min(tgl) AS dari, max(tgl) AS sampai
FROM stg_spb_2608;
